199	diff --git a/harper-yaml/src/dedent.rs b/harper-yaml/src/dedent.rs
200	new file mode 100644
201	index 00000000..828c0ebe
202	--- /dev/null
203	+++ b/harper-yaml/src/dedent.rs
204	@@ -0,0 +1,120 @@
205	+use harper_core::parsers::Parser;
206	+use harper_core::{Span, Token, TokenKind};
207	+
208	+/// Wraps a `Parser`, parsing each line of a (possibly multiline) span
209	+/// independently after trimming its leading/trailing whitespace, then
210	+/// stitching the results back together with a single explicit
211	+/// [`TokenKind::Newline`] token between lines.
212	+///
213	+/// This exists for YAML block/folded scalars: their continuation lines
214	+/// carry literal indentation (e.g. two leading spaces). Feeding
215	+/// that raw text straight to a prose parser makes the newline-plus-
216	+/// indentation read as a run of several space characters, which
217	+/// incorrectly triggers Harper's "double space" formatting rule.
218	+/// De-denting each line before parsing avoids that, without needing to
219	+/// understand YAML's specific indentation rules.
220	+pub(crate) struct DedentLines<P> {
221	+    inner: P,
222	+}
223	+
224	+impl<P: Parser> DedentLines<P> {
225	+    pub(crate) fn new(inner: P) -> Self {
226	+        Self { inner }
227	+    }
228	+}
229	+
230	+impl<P: Parser> Parser for DedentLines<P> {
231	+    fn parse(&self, source: &[char]) -> Vec<Token> {
232	+        let mut tokens = Vec::new();
233	+        let mut chars_traversed = 0;
234	+
235	+        for line in source.split(|c| *c == '\n') {
236	+            if let Some(trimmed) = trim(line) {
237	+                let mut new_tokens = self.inner.parse(trimmed.get_content(line));
238	+
239	+                new_tokens
240	+                    .iter_mut()
241	+                    .for_each(|t| t.span.push_by(chars_traversed + trimmed.start));
242	+
243	+                tokens.append(&mut new_tokens);
244	+            }
245	+
246	+            let line_end = chars_traversed + line.len();
247	+
248	+            if line_end < source.len() {
249	+                tokens.push(Token::new(
250	+                    Span::new_with_len(line_end, 1),
251	+                    TokenKind::Newline(1),
252	+                ));
253	+            }
254	+
255	+            chars_traversed += line.len() + 1;
256	+        }
257	+
258	+        tokens
259	+    }
260	+}
261	+
262	+/// The span of `line` with leading/trailing whitespace trimmed, or
263	+/// `None` if the line is entirely whitespace.
264	+fn trim(line: &[char]) -> Option<Span<char>> {
265	+    let start = line.iter().position(|c| !c.is_whitespace())?;
266	+    let end = line.len() - line.iter().rev().position(|c| !c.is_whitespace())?;
267	+
268	+    Some(Span::new(start, end))
269	+}
270	+
271	+#[cfg(test)]
272	+mod tests {
273	+    use harper_core::TokenKind;
274	+    use harper_core::parsers::{Parser, PlainEnglish};
275	+
276	+    use super::DedentLines;
277	+
278	+    fn parse(source: &str) -> Vec<harper_core::Token> {
279	+        let chars: Vec<char> = source.chars().collect();
280	+        DedentLines::new(PlainEnglish).parse(&chars)
281	+    }
282	+
283	+    #[test]
284	+    fn dedents_indented_continuation_line() {
285	+        let source = "hello\n  world";
286	+        let tokens = parse(source);
287	+
288	+        // No token should be a run of more than one space - the two
289	+        // leading spaces before "world" must have been trimmed away.
290	+        for token in &tokens {
291	+            if let TokenKind::Space(count) = token.kind {
292	+                assert_eq!(count, 1, "found a multi-space token: {tokens:?}");
293	+            }
294	+        }
295	+    }
296	+
297	+    #[test]
298	+    fn inserts_single_newline_between_lines() {
299	+        let tokens = parse("hello\nworld");
300	+        let newline_count = tokens
301	+            .iter()
302	+            .filter(|t| matches!(t.kind, TokenKind::Newline(_)))
303	+            .count();
304	+
305	+        assert_eq!(newline_count, 1);
306	+    }
307	+
