315	+    fn spans_map_back_to_original_source() {
316	+        let source = "hello\n  world";
317	+        let chars: Vec<char> = source.chars().collect();
318	+        let tokens = parse(source);
319	+
320	+        for token in &tokens {
321	+            assert!(token.span.try_get_content(&chars).is_some());
322	+        }
323	+    }
324	+}
