329	+++ b/harper-yaml/src/heuristics.rs
330	@@ -0,0 +1,211 @@
331	+/// Decides whether a YAML scalar value looks like prose worth
332	+/// grammar-checking, as opposed to structural config data
333	+/// (identifiers, enum values, URLs, paths, version strings).
334	+///
335	+/// Comments are never passed through this function — they're
336	+/// always linted, handled separately in `YamlMasker`.
337	+pub(crate) fn is_prose_scalar(text: &str) -> bool {
338	+    let word_count = text.split_whitespace().count();
339	+
340	+    word_count >= 3 && !looks_url_path_or_version(text) && !looks_like_identifier(text)
341	+}
342	+
343	+/// True only if `text` is, in its entirety, a single whitespace-separated
344	+/// token that is itself URL-, path-, or version-shaped (e.g. `v1.2.3`,
345	+/// `0.15.9`, `https://example.com`, `/usr/local/bin`) — not merely a
346	+/// sentence that happens to mention one (e.g. "Update the library to
347	+/// version 1.2.3" is prose worth checking, not a bare version string).
348	+///
349	+/// A value with 3+ words already fails `is_prose_scalar`'s word-count
350	+/// gate before this function's result can matter, so in practice this
351	+/// only ever returns `true` for single-token values. Kept explicit and
352	+/// correct on its own terms rather than relying on that gate implicitly.
353	+fn looks_url_path_or_version(text: &str) -> bool {
354	+    let mut words = text.split_whitespace();
355	+
356	+    let Some(only_word) = words.next() else {
357	+        return false;
358	+    };
359	+
360	+    if words.next().is_some() {
361	+        return false;
362	+    }
363	+
364	+    only_word.starts_with("http://")
365	+        || only_word.starts_with("https://")
366	+        || only_word.starts_with("ftp://")
367	+        || only_word.contains('/')
368	+        || only_word.contains('\\')
369	+        || is_semver_like(only_word)
370	+}
371	+
372	+/// Matches strings shaped like `1.2.3`, `v1.2.3`, or `12.34.56.7`
373	+/// (semver-ish): an optional leading `v`/`V`, then digit groups
374	+/// separated by dots, at least two dots, no other characters.
375	+fn is_semver_like(word: &str) -> bool {
376	+    let trimmed = word.trim_matches(|c: char| !c.is_ascii_alphanumeric());
377	+    let trimmed = trimmed.strip_prefix(['v', 'V']).unwrap_or(trimmed);
378	+    let parts: Vec<&str> = trimmed.split('.').collect();
379	+
380	+    parts.len() >= 3
381	+        && parts
382	+            .iter()
383	+            .all(|p| !p.is_empty() && p.chars().all(|c| c.is_ascii_digit()))
384	+}
385	+
386	+/// True if the whole value reads as an identifier/enum/constant
387	+/// rather than a sentence: entirely uppercase, or snake_case, or
388	+/// kebab-case.
389	+fn looks_like_identifier(text: &str) -> bool {
390	+    let has_letters = text.chars().any(|c| c.is_alphabetic());
391	+
392	+    if !has_letters {
393	+        return false;
394	+    }
395	+
396	+    let is_all_caps = text.chars().any(|c| c.is_alphabetic())
397	+        && text
398	+            .chars()
399	+            .filter(|c| c.is_alphabetic())
400	+            .all(|c| c.is_uppercase());
401	+
402	+    if is_all_caps {
403	+        return true;
404	+    }
405	+
406	+    is_snake_or_kebab_case(text)
407	+}
408	+
409	+/// True if the entire string is a single token of the shape
410	+/// `word(_word)*` or `word(-word)*` with no spaces — i.e. it reads
411	+/// as one identifier, not a sentence.
412	+fn is_snake_or_kebab_case(text: &str) -> bool {
413	+    if text.contains(char::is_whitespace) {
414	+        return false;
415	+    }
416	+
417	+    let is_snake = text.contains('_')
418	+        && text
419	+            .chars()
420	+            .all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '_');
421	+
422	+    let is_kebab = text.contains('-')
423	+        && text
424	+            .chars()
425	+            .all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '-');
426	+
427	+    is_snake || is_kebab
428	+}
429	+
